$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$overviewApi = Decode ""
$bookingsPage = Decode ""

$apiPath = Join-Path $root "app\api\bookings\overview\route.ts"
$pagePath = Join-Path $root "app\bookings\page.tsx"
$groupPath = Join-Path $root "app\booking-groups\[id]\page.tsx"
$brainPath = Join-Path $root "app\api\brain\actions\route.ts"

foreach ($path in @($pagePath, $groupPath, $brainPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.92 : fichier requis introuvable : $path"
    }
}

$group = [System.IO.File]::ReadAllText($groupPath)
$brain = [System.IO.File]::ReadAllText($brainPath)

if (-not $group.Contains("KLYX_GROUP_MISSION_PAGE_12_87")) {
    throw "12.92 : mission groupee 12.87 introuvable."
}

if (-not $brain.Contains("KLYX_GROUP_ACTION_CENTER_12_91")) {
    throw "12.92 : Action Center 12.91 introuvable."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $apiPath) | Out-Null

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-12-92-" + $timestamp) -Force

if (Test-Path -LiteralPath $apiPath) {
    Copy-Item -LiteralPath $apiPath -Destination ($apiPath + ".bak-12-92-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($apiPath, $overviewApi, $utf8)
[System.IO.File]::WriteAllText($pagePath, $bookingsPage, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.92 APPLIQUE"
Write-Host "======================================"
Write-Host "1 groupe = 1 carte : OK"
Write-Host "Enfants groupes masques : OK"
Write-Host "Reservations classiques : CONSERVEES"
Write-Host "Client + prestataire : OK"
Write-Host "Annulation 12.90 : INTEGREE"
Write-Host "Action Center 12.91 : CONSERVE"
Write-Host "======================================"
Write-Host ""
